  countrySpinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int pos,long id){selectCountry(pos);}public void onNothingSelected(AdapterView<?> a){}});categoriesView.setOnItemClickListener((a,v,pos,id)->selectCategory(pos,false));channelsView.setOnItemClickListener((a,v,pos,id)->activateChannel(pos,false));overlayCategories.setOnItemClickListener((a,v,pos,id)->selectCategory(pos,true));overlayChannels.setOnItemClickListener((a,v,pos,id)->activateChannel(pos,true));
